	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		_main = this;
		
		window.onresize = function () {
			
			moveElements();
			
		};
		function moveElements() {
			var domOverlay = document.getElementById("dom_overlay_container");
		
			
			var nowW, nowH;
		
			nowW = nowW = window.banner.clientWidth;
		
			canvas.width = domOverlay.width = nowW * window.devicePixelRatio;
			canvas.style.width = domOverlay.style.width = nowW + "px";
			
				_main.fon.x = nowW/2;
			
				if(nowW >= 728&& nowW < 8192){
				_main.banner_big.visible = true;
				_main.banner_mini.visible = false;
				_main.banner_big.x = nowW/2;
				}
			
				if(nowW >= 320 && nowW < 728){
				_main.banner_big.visible = false;
				_main.banner_mini.visible = true;
				_main.banner_mini.x = nowW/2;
				}	
			
			};
		
		moveElements();
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// big
	this.banner_big = new lib._main_1500();
	this.banner_big.name = "banner_big";
	this.banner_big.setTransform(750,125);

	this.timeline.addTween(cjs.Tween.get(this.banner_big).wait(1));

	// mini
